SELECT DISTINCT metadata->>'file_hash' AS file_hash
FROM   rag_chunks
WHERE  jsonb_exists(metadata, 'file_hash');

INSERT INTO rag_documents (file_name, file_path, file_hash, doc_type, sensitivity)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (file_hash) DO NOTHING;

SELECT table_name, column_name, full_name, section_name, unit, data_type, valid_categories, description
FROM   data_dictionary
ORDER  BY table_name, section_name, column_name;
